import{_ as a,o as i,c as s,a8 as t}from"./chunks/framework.DpokcgZS.js";const u=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/compatibility.md","filePath":"en/guide/compatibility.md","lastUpdated":1792664051000}'),r={name:"en/guide/compatibility.md"};function n(l,e,o,d,p,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><h2 id="package-and-api-versions" tabindex="-1">Package and API versions <a class="header-anchor" href="#package-and-api-versions" aria-label="Permalink to &quot;Package and API versions&quot;">​</a></h2><p>Vue <code>3.0+</code> is supported. Stable releases use the default <code>latest</code> channel:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue-fullscreen</span></span></code></pre></div><p>This API reference describes <code>5.0.0</code>. For Vue 2, use <code>vue-fullscreen@legacy</code>; see <a href="/en/vue2/guide/compatibility">Vue 2 compatibility</a>.</p><h2 id="fullscreen-api-browser-support" tabindex="-1">Fullscreen API browser support <a class="header-anchor" href="#fullscreen-api-browser-support" aria-label="Permalink to &quot;Fullscreen API browser support&quot;">​</a></h2><p>Native fullscreen is provided by the browser. See <a href="https://caniuse.com/fullscreen" target="_blank" rel="noreferrer">Can I use: Fullscreen API</a> for version coverage and <a href="https://developer.mozilla.org/en-US/docs/Web/API/Element/requestFullscreen#browser_compatibility" target="_blank" rel="noreferrer">MDN&#39;s requestFullscreen compatibility table</a> for device restrictions.</p><table tabindex="0"><thead><tr><th>Browser / device</th><th>Native fullscreen support</th></tr></thead><tbody><tr><td>Desktop Chrome / Edge</td><td>Standard API in Chrome 71+ and Edge 79+</td></tr><tr><td>Desktop Firefox</td><td>Standard API in 64+</td></tr><tr><td>macOS Safari</td><td>Standard API in 16.4+; earlier versions have partial prefixed support</td></tr><tr><td>iPad Safari</td><td>Standard API in iPadOS 16.4+, with device restrictions; earlier versions have partial prefixed support</td></tr><tr><td>iPhone Safari</td><td>No Fullscreen API for arbitrary elements; use page-only mode</td></tr><tr><td>Android Chrome / Firefox</td><td>Supported in current versions; see the support table for individual releases</td></tr><tr><td>Internet Explorer</td><td>IE 11 has partial native API support; this package does not support IE</td></tr></tbody></table><p>These versions describe the browser API, not this package&#39;s minimum browser versions or a promise of testing on each device. Package builds target ES2018. The underlying <code>screenfull</code> library handles some vendor prefixes, but cannot supply missing browser capabilities.</p><h3 id="safari-and-mobile-devices" tabindex="-1">Safari and mobile devices <a class="header-anchor" href="#safari-and-mobile-devices" aria-label="Permalink to &quot;Safari and mobile devices&quot;">​</a></h3><p>iPad fullscreen displays browser-provided exit controls, and system gestures such as swiping down may exit fullscreen. The iPhone video player&#39;s dedicated fullscreen feature does not provide native fullscreen for charts, ordinary <code>div</code> elements or the whole page. See the <a href="https://webkit.org/blog/13966/webkit-features-in-safari-16-4/" target="_blank" rel="noreferrer">WebKit release notes</a> for Safari 16.4 changes.</p><h3 id="internet-explorer" tabindex="-1">Internet Explorer <a class="header-anchor" href="#internet-explorer" aria-label="Permalink to &quot;Internet Explorer&quot;">​</a></h3><p>This package requires Vue 3 and does not support IE. Adding a <code>Promise</code> polyfill cannot supply the Proxy support required by Vue 3. For IE 11, use the separate <a href="/en/vue2/guide/compatibility">Vue 2 package and compatibility guide</a>.</p><h2 id="user-activation-and-iframe-permissions" tabindex="-1">User activation and iframe permissions <a class="header-anchor" href="#user-activation-and-iframe-permissions" aria-label="Permalink to &quot;User activation and iframe permissions&quot;">​</a></h2><p>Native fullscreen <strong>can only be triggered by</strong> a user interaction such as a click, touch or key press. Avoid waiting for a network request before calling the API, as user activation may expire.</p><p>An embedded document needs fullscreen permission, for example:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/example/&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> allow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fullscreen&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> allowfullscreen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The parent document&#39;s <code>Permissions-Policy</code> can still restrict fullscreen. An iframe attribute cannot override a stricter response-header policy.</p><h2 id="capability-detection-and-page-only-fallback" tabindex="-1">Capability detection and page-only fallback <a class="header-anchor" href="#capability-detection-and-page-only-fallback" aria-label="Permalink to &quot;Capability detection and page-only fallback&quot;">​</a></h2><p>Read the <code>isSupported</code> ref returned by <code>useFullscreen()</code> in the browser to check whether the current document allows native fullscreen. It does not indicate whether fullscreen is active or guarantee that the next request will succeed.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { useFullscreen } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vue-fullscreen&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Read after mount or during a user interaction</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">isSupported</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useFullscreen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nativeAvailable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> isSupported.value</span></span></code></pre></div><ul><li>When native fullscreen is unavailable, the component, directive and API fall back to page-only mode.</li><li>Explicitly setting <code>pageOnly: true</code> (<code>page-only</code> on the component) always uses page-only mode.</li><li>If the native capability is available but a request is rejected, the library reports the error and restores the DOM without silently falling back. Catch API Promise rejections; use the component&#39;s <code>error</code> event or the directive&#39;s <code>fullscreen-error</code> event.</li></ul><p>Page-only mode keeps the browser toolbar and fills only the current document&#39;s viewport. Inside an iframe, it fills the frame. <code>teleport</code> moves the target to that document&#39;s <code>body</code>; it cannot escape the iframe boundary.</p>`,23)])])}const k=a(r,[["render",n]]);export{u as __pageData,k as default};
